/** Returns the CREATE statements for the given tables in their original creation order */
export function astroGeneratedSchemaFor(tables) {
  return ASTRO_GENERATED_SCHEMA.filter((entry) => tables.includes(entry.table)).map((entry) => entry.sql)
}
